    internal static int DtSurvive(emon.Port.Src pdf, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells pg, emon.Port.Cells @out) {
        // Open, list the pages, and decode every stream the cross-reference
        // names: none of it may fault. Answers the pd-open status.
        int status = DtOpen(pdf, ar, dc, a, b, st, pg);
        int i = 1;
        int h = 0;
        if (status == 0) {
            while (i < Pdfdoc.PdObjectCount(dc)) {
                h = Pdfdoc.PdGet(pdf, ar, dc, a, b, st, i);
                if (h != 0) {
                    if (Pdflex.PlKindOf(ar, h) == 8) {
                        Pdfdoc.PdStreamData(pdf, ar, dc, a, b, st, h, @out);
                    }
                }
                i += 1;
            }
        }
        return status;
    }
    internal static int DtCut(byte[] f, int n, emon.Port.Cells cut) {
        // cut = the first n bytes of f.
        int i = 0;
        emon.Port.CellsDrop(cut, 0);
        while (i < n) {
            emon.Port.CellsPush(cut, emon.Port.BlobU8(f, i));
            i += 1;
        }
        return n;
    }
    internal static int DtTruncations(byte[] f, int step, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells pg, emon.Port.Cells @out, emon.Port.Cells cut) {
        // Every truncation of f (every `step` bytes): none may fault. Answers
        // how many still opened.
        int n = emon.Port.BlobLen(f);
        int k = 0;
        int ok = 0;
        while (k <= n) {
            DtCut(f, k, cut);
            if (DtSurvive(emon.Port.SrcOfBlob(emon.Testport.CellsBlob(cut)), ar, dc, a, b, st, pg, @out) == 0) {
                ok += 1;
            }
            k += step;
        }
        return ok;
    }
    internal static int DtCorruptions(byte[] f, int rounds, int flips, int seed, emon.Port.Cells ar, emon.Port.Cells dc, emon.Port.Cells a, emon.Port.Cells b, emon.Port.Cells st, emon.Port.Cells pg, emon.Port.Cells @out, emon.Port.Cells cut, emon.Port.Cells rng) {
        // `rounds` copies of f, each with `flips` random bytes replaced
        // (SplitMix, so every target damages the same bytes): none may fault.
        int n = emon.Port.BlobLen(f);
        int r = 0;
        int j = 0;
        int at = 0;
        int ok = 0;
        Splitmix.SmSeed(rng, (long) seed);
        while (r < rounds) {
            DtCut(f, n, cut);
            j = 0;
            while (j < flips) {
                at = Splitmix.SmBelow(rng, n);
                emon.Port.CellsSet(cut, at, Splitmix.SmBelow(rng, 256));
                j += 1;
            }
            if (DtSurvive(emon.Port.SrcOfBlob(emon.Testport.CellsBlob(cut)), ar, dc, a, b, st, pg, @out) == 0) {
                ok += 1;
            }
            r += 1;
        }
        return ok;
    }
